.panel { background: white; border: 1px solid var(--line); border-radius: 20px; box-shadow: 0 12px 35px #23395d0b; padding: 28px; }
.section-heading { display: flex; gap: 14px; align-items: flex-start; margin-bottom: 25px; } .step { color: var(--blue); background: var(--pale); border-radius: 8px; padding: 7px 8px; font-size: 11px; font-weight: 800; letter-spacing: .06em; } h2 { margin: 0 0 4px; font-size: 19px; } .section-heading p { margin: 0; color: var(--muted); font-size: 13px; }
.field { margin-bottom: 17px; } .field-row { display: grid; grid-template-columns: 1fr 1fr; gap: 13px; } label { display: block; margin-bottom: 7px; font-size: 12px; font-weight: 750; color: #39475a; }
