.primary-button { width: 100%; border: 0; border-radius: 10px; padding: 13px 17px; color: white; background: var(--blue); font: inherit; font-weight: 750; cursor: pointer; transition: transform .15s, background .15s; } .primary-button:hover { background: #3155c4; transform: translateY(-1px); } .primary-button span { float: right; font-size: 18px; line-height: 15px; }.privacy-note { margin: 14px 0 0; color: #9aa6b5; text-align: center; font-size: 11px; }.form-error { min-height: 18px; margin: -4px 0 9px; color: #c13d50; font-size: 12px; }.confirmation { padding: 12px 14px; margin: -4px 0 20px; border: 1px solid #b9e6d4; border-radius: 10px; color: #176344; background: var(--mint); font-size: 13px; font-weight: 650; }
.booking-list { display: grid; gap: 12px; }.empty-state { min-height: 260px; display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 7px; color: #9aa6b5; text-align: center; border: 1px dashed #dce3eb; border-radius: 14px; }.empty-state strong { color: #657287; font-size: 14px; }.empty-state span { font-size: 12px; }.empty-icon { color: var(--blue); font-size: 33px; margin-bottom: 4px; }
