function localDateString(date = new Date()) {
  const offset = date.getTimezoneOffset() * 60000;
  return new Date(date.getTime() - offset).toISOString().slice(0, 10);
}
dateInput.min = localDateString();

function render() {
  list.innerHTML = '';
  if (!bookings.length) {
