    name.dataset.testid = 'booking-name-display';
    name.textContent = booking.name;
    const meta = document.createElement('div');
    meta.className = 'booking-meta';
    const appointmentDate = new Date(`${booking.date}T${booking.time}`);
    meta.textContent = `${appointmentDate.toLocaleDateString(undefined, { weekday: 'short', month: 'short', day: 'numeric', year: 'numeric' })} · ${appointmentDate.toLocaleTimeString(undefined, { hour: 'numeric', minute: '2-digit' })} · ${booking.email}`;
