<!doctype html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Appointment Booking Form</title>
  <link rel="stylesheet" href="styles.css">
  <script src="script.js" defer></script>
</head>
<body>
  <main class="shell">
    <section class="hero">
      <div class="brand-mark" aria-hidden="true">✦</div>
      <div>
        <p class="eyebrow">Simple scheduling</p>
        <h1>Book an appointment</h1>
        <p class="intro">Choose a convenient time and we’ll keep your appointment details right here in this browser.</p>
      </div>
    </section>

    <div class="layout">
      <section class="panel form-panel" aria-labelledby="form-title">
        <div class="section-heading">
          <span class="step">01</span>
          <div>
            <h2 id="form-title">Appointment details</h2>
            <p>All fields are required.</p>
          </div>
        </div>
        <form id="booking-form">
          <div class="field">
            <label for="booking-name">Customer name</label>
            <input id="booking-name" data-testid="booking-name" name="name" type="text" placeholder="e.g. Jordan Lee" autocomplete="name" required>
          </div>
          <div class="field">
            <label for="booking-email">Email address</label>
            <input id="booking-email" data-testid="booking-email" name="email" type="email" placeholder="you@example.com" autocomplete="email" required>
          </div>
          <div class="field-row">
            <div class="field">
              <label for="booking-date">Date</label>
              <input id="booking-date" data-testid="booking-date" name="date" type="date" required>
            </div>
            <div class="field">
              <label for="booking-time">Time</label>
              <input id="booking-time" data-testid="booking-time" name="time" type="time" required>
            </div>
          </div>
          <div class="field">
            <label for="booking-type">Appointment type</label>
            <select id="booking-type" data-testid="booking-type" name="type" required>
              <option value="" selected disabled>Select a service</option>
              <option value="Consultation">Consultation</option>
              <option value="Follow-up">Follow-up</option>
              <option value="Wellness check">Wellness check</option>
              <option value="Project review">Project review</option>
            </select>
          </div>
          <p class="form-error" id="form-error" role="alert"></p>
          <button class="primary-button" data-testid="booking-submit" type="submit">Confirm appointment <span>→</span></button>
          <p class="privacy-note">Your booking stays in this page and is never sent anywhere.</p>
        </form>
      </section>

      <section class="panel bookings-panel" aria-labelledby="bookings-title">
        <div class="section-heading list-heading">
