const form = document.getElementById('booking-form');
const dateInput = document.querySelector('[data-testid="booking-date"]');
const list = document.querySelector('[data-testid="booking-list"]');
const confirmation = document.querySelector('[data-testid="booking-confirmation"]');
const error = document.getElementById('form-error');
const count = document.getElementById('booking-count');
let bookings = [];

function localDateString(date = new Date()) {
  const offset = date.getTimezoneOffset() * 60000;
  return new Date(date.getTime() - offset).toISOString().slice(0, 10);
}
dateInput.min = localDateString();

function render() {
  list.innerHTML = '';
  if (!bookings.length) {
    list.innerHTML = '<div class="empty-state"><div class="empty-icon">◷</div><strong>Your schedule is clear</strong><span>Created appointments will appear here.</span></div>';
    count.textContent = 'No appointments yet';
    return;
  }
  const active = bookings.filter(b => !b.cancelled).length;
  count.textContent = `${active} active appointment${active === 1 ? '' : 's'}`;
  bookings.forEach((booking, index) => {
    const card = document.createElement('article');
    card.className = 'booking' + (booking.cancelled ? ' cancelled' : '');
    card.dataset.testid = 'booking';
    card.dataset.status = booking.cancelled ? 'cancelled' : 'active';
    const top = document.createElement('div'); top.className = 'booking-top';
    const details = document.createElement('div');
    const name = document.createElement('h3'); name.className = 'booking-name'; name.dataset.testid = 'booking-name-display'; name.textContent = booking.name;
    const meta = document.createElement('div'); meta.className = 'booking-meta';
    const date = new Date(`${booking.date}T${booking.time}`);
    meta.textContent = `${date.toLocaleDateString(undefined, {weekday:'short', month:'short', day:'numeric', year:'numeric'})} · ${date.toLocaleTimeString(undefined, {hour:'numeric', minute:'2-digit'})} · ${booking.email}`;
    details.append(name, meta); top.appendChild(details);
    const badge = document.createElement('span'); badge.className = 'badge'; badge.textContent = booking.type; top.appendChild(badge); card.appendChild(top);
    if (booking.cancelled) { const label = document.createElement('div'); label.className = 'cancelled-label'; label.textContent = 'Cancelled'; card.appendChild(label); }
    else { const cancel = document.createElement('button'); cancel.type = 'button'; cancel.className = 'cancel-button'; cancel.dataset.testid = 'booking-cancel'; cancel.textContent = 'Cancel appointment'; cancel.addEventListener('click', () => { bookings[index].cancelled = true; render(); }); card.appendChild(cancel); }
    list.appendChild(card);
  });
}
form.addEventListener('submit', event => {
  event.preventDefault(); error.textContent = ''; confirmation.hidden = true;
  if (!form.checkValidity()) { form.reportValidity(); return; }
  if (dateInput.value < localDateString()) { error.textContent = 'Please choose today or a future date.'; dateInput.focus(); return; }
  const data = new FormData(form);
  const booking = { name: data.get('name').trim(), email: data.get('email').trim(), date: data.get('date'), time: data.get('time'), type: data.get('type'), cancelled: false };
  bookings.push(booking); render(); form.reset(); dateInput.min = localDateString();
  confirmation.textContent = `Appointment confirmed for ${booking.name}.`; confirmation.hidden = false;
});
render();

